X, y = data(60, 3, 3)

def gm(ct: Literal[str], ini: str, w, m, c, p, it: int, lb: float, ss, pp, bic: float, aic: float):
    g = GaussianMixture(3, covariance_type=ct, init_params=ini, random_state=0, max_iter=200).fit(X)
    tag = "gm_" + ct + "_" + ini
    close(tag + "_w", g.weights_, w, 1e-5); close(tag + "_m", g.means_, m, 1e-5)
    close(tag + "_c", g.covariances_, c, 1e-5); close(tag + "_p", g.precisions_, p, 1e-5)
    if g.n_iter_ != it:
        print("TEST FAILED", tag, "n_iter", g.n_iter_, it)
    closes(tag + "_lb", g.lower_bound_, lb); close(tag + "_ss", g.score_samples(X[:5]), ss, 1e-5)
    close(tag + "_pp", g.predict_proba(X[:3]), pp, 1e-5, 1e-7)
    closes(tag + "_bic", g.bic(X), bic); closes(tag + "_aic", g.aic(X), aic)

